/**
 * Renders the desk page's PR artifacts from a seeded sample desk: PNG stills and a walk-through GIF.
 *
 *   cd .opencode && bun run artifacts [out-dir]        # default: $TMPDIR/desk-artifacts
 *   scripts/pr-artifacts.sh <branch> <out-dir>/*       # publish
 *
 * The page runs on the plugin's own layers (`App.desk`) with recorded sessions instead of OpenCode, in a temporary
 * checkout whose `coordination/` holds only the sample generated from `seed` (see `sample.ts`), plus a GIF and a
 * video generated by ffmpeg. Nothing is read from any real `coordination/`.
 *
 * Needs Google Chrome (driven headless through playwright-core) and ffmpeg.
 */
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
import * as HttpServer from "effect/http/HttpServer";
import * as Layer from "effect/Layer";
import * as Scope from "effect/Scope";
import { chromium, type Page } from "playwright-core";
import * as App from "../app";
import { Desk } from "../desk";
import { fileName, serialize } from "../entry";
import { Sessions } from "../sessions";
import { sample } from "./sample";

/** Change it to get a different sample desk; the artifacts are the same for the same seed. */
const seed = 30;
const { entries, images, roles } = sample(seed);
const out = process.argv[2] ?? join(tmpdir(), "desk-artifacts");

function ffmpeg(...args: Array<string>) {
	const result = Bun.spawnSync(["ffmpeg", "-loglevel", "error", "-y", ...args], { stderr: "pipe" });
	if (result.exitCode !== 0) throw new Error(`ffmpeg ${args.join(" ")}: ${result.stderr.toString()}`);
}

/** Writes the sample into `<root>/coordination` and generates its GIF and video. */
async function prepare(root: string) {
	const coordination = join(root, "coordination");
	const media = join(coordination, "media");
	await mkdir(media, { recursive: true });
	for (const entry of entries) await writeFile(join(coordination, fileName(entry.id)), serialize(entry));
	for (const [name, svg] of Object.entries(images)) await writeFile(join(media, name), svg);
	ffmpeg("-f", "lavfi", "-i", "testsrc2=size=480x270:rate=12:duration=3", "-vf", "split[a][b];[a]palettegen[p];[b][p]paletteuse", join(media, "demo.gif"));
	ffmpeg("-f", "lavfi", "-i", "testsrc2=size=480x270:rate=30:duration=3", "-pix_fmt", "yuv420p", join(media, "demo.mp4"));
}

/** Waits for images, video posters and Mermaid diagrams on the page. */
async function settle(page: Page) {
	await page.waitForSelector("header"); // rendered once the first view arrives
	await page.waitForFunction(() =>
		[...document.images].every((image) => image.complete) &&
		[...document.querySelectorAll("video")].every((video) => video.readyState >= 2) &&
		[...document.querySelectorAll(".mermaid")].every((diagram) => diagram.querySelector("svg")),
	);
	await page.waitForTimeout(300);
}

const temp = await mkdtemp(join(tmpdir(), "desk-artifacts-"));
/** Named like the real checkout, since the page shows the checkout's name. */
const root = join(temp, "phantom");
const scope = Effect.runSync(Scope.make());
const browser = await chromium.launch({ channel: "chrome", headless: true });
try {
	await prepare(root);
	await rm(out, { recursive: true, force: true });
	await mkdir(join(out, ".frames"), { recursive: true });

	const live = App.desk(root, 0).pipe(Layer.provide(Sessions.memory([])));
	const services = await Effect.runPromise(Layer.buildWithScope(live, scope));
	const address = Context.get(services, HttpServer.HttpServer).address;
	const url = `http://127.0.0.1:${address._tag === "UnixPathAddress" ? 0 : address.port}/`;

	// Stills: 1000 px wide at 2x, full page.
	const stills: Array<[name: string, path: string, scheme: "light" | "dark"]> = [
		["desk-list", "#/", "light"],
		["desk-entry-images", `#/${roles.images}`, "light"],
		["desk-entry-mermaid", `#/${roles.diagram}`, "light"],
		["desk-entry-video", `#/${roles.video}`, "light"],
		["desk-entry-nested", `#/${roles.video}`, "light"],
		["desk-entry-dark", `#/${roles.family}`, "dark"],
	];
	for (const [name, path, scheme] of stills) {
		const context = await browser.newContext({ viewport: { width: 1000, height: 900 }, deviceScaleFactor: 2, colorScheme: scheme });
		// One answer is started, as in the browser's draft store.
		await context.addInitScript(([id, deep]) => localStorage.setItem("desk.drafts", JSON.stringify({ [id]: "Yes, keep them consistent.", [deep]: "Yes." })), [roles.mine, roles.deep] as const);
		const page = await context.newPage();
		await page.goto(`${url}${path}`);
		await settle(page);
		await page.screenshot({ path: join(out, `${name}.png`), fullPage: true });
		await context.close();
		console.log(`wrote ${name}.png`);
	}

	// The walk-through: list → an entry → type → an agent's follow-up arrives → back to the list → your own question → Mark done → Next → Submit.
	const context = await browser.newContext({ viewport: { width: 1000, height: 760 }, colorScheme: "light" });
	const page = await context.newPage();
	let frame = 0;
	const snap = async (count = 1) => {
		for (let i = 0; i < count; i++) await page.screenshot({ path: join(out, ".frames", `frame_${String(frame++).padStart(4, "0")}.png`) });
	};
	await page.goto(url);
	await settle(page);
	await snap(18);
	await page.click(`.list a[href="#/${roles.walk}"]`);
	await settle(page);
	await snap(10);
	await page.click("textarea");
	for (const char of "Yes, keep them consistent.") {
		await page.keyboard.type(char);
		await snap();
	}
	await snap(6);
	// An agent follows up meanwhile.
	const followUp = await Effect.runPromise(
		Effect.provideContext(
			Desk.use((desk) =>
				desk.ask("ses_main", { title: "And for torrents added from the menu bar?", body: "Those skip the add dialog.", parent: roles.walk }),
			),
			services,
		),
	);
	await page.waitForSelector(`.children a[href="#/${followUp.id}"]`);
	await snap(16);
	await page.click("text=← All entries");
	await settle(page);
	await snap(10);
	await page.click(`.list a[href="#/${roles.mine}"]`);
	await settle(page);
	await snap(14);
	await page.click("text=Mark done");
	await page.waitForSelector("text=no longer on the desk");
	await snap(14);
	await page.click(".nav button.primary");
	await settle(page);
	await snap(10);
	await page.click("header button.primary");
	await page.waitForSelector(".toast");
	await snap(22);
	await context.close();

	ffmpeg("-framerate", "12", "-i", join(out, ".frames", "frame_%04d.png"), "-vf", "scale=900:-1:flags=lanczos,split[a][b];[a]palettegen[p];[b][p]paletteuse", join(out, "desk-walk.gif"));
	await rm(join(out, ".frames"), { recursive: true, force: true });
	console.log(`wrote desk-walk.gif\n\nArtifacts in ${out}. Publish: scripts/pr-artifacts.sh <branch> ${out}/*`);
} finally {
	await browser.close();
	await Effect.runPromise(Scope.close(scope, Exit.void));
	await rm(temp, { recursive: true, force: true });
}
